<script setup>
import {computed,ref,watch} from 'vue'
import {cspPresets,ac3Steps,treeCspSteps} from '../services/csp-search.mjs'
import SimulationControls from './SimulationControls.vue'
import SearchTraceCode from './SearchTraceCode.vue'
import CspStateView from './CspStateView.vue'
const props=defineProps({preset:{type:String,default:'chain'}})
const preset=ref(props.preset),mode=ref(props.preset==='tree'?'tree':'ac3'),step=ref(0)
const problem=computed(()=>cspPresets[preset.value].create())
const computation=computed(()=>{try{return {trace:Array.from(mode.value==='tree'?treeCspSteps(problem.value):ac3Steps(problem.value)),error:''}}catch(e){return {trace:[],error:e.message}}})
const state=computed(()=>computation.value.trace[Math.min(step.value,computation.value.trace.length-1)]),key=computed(()=>preset.value+mode.value)
watch(key,()=>step.value=0)
const message=computed(()=>{const s=state.value;if(!s)return '';if(s.phase==='failure')return 'Một miền đã rỗng. CSP hiện tại không có nghiệm.';if(s.phase==='success')return 'Gán tiến hoàn tất, thu được một nghiệm trên cây.';if(s.phase==='consistent')return 'Mọi cung đã nhất quán. Các miền không rỗng, nhưng điều này chưa chứng minh CSP có nghiệm. Hãy thử tam giác hai màu.';if(s.phase==='arc')return `Lấy cung ${s.arc.join(' → ')} khỏi đầu hàng đợi. Tìm hỗ trợ ở biến thứ hai cho từng giá trị của biến thứ nhất.`;if(s.phase==='revise')return `REVISE(${s.arc.join(', ')}): Xóa ${s.removed.join(', ')||'không có giá trị nào'} khỏi miền ${s.arc[0]}.`;if(s.phase==='enqueue')return 'Miền ở đầu cung vừa thay đổi. Đưa các cung hướng vào biến ấy trở lại hàng đợi, bỏ cung ngược vừa xét.';if(s.phase==='assign')return `Gán tiến ${s.variable} = ${s.value}, thỏa mãn ràng buộc với cha đã gán.`;return mode.value==='tree'?'Xếp cha trước con, sau đó lọc từ cuối danh sách về gốc.':'Khởi tạo hàng đợi gồm cả hai hướng của mỗi cạnh ràng buộc.'})
</script>
<template><section class="math-lab csp-arc" aria-label="Mô phỏng AC-3 và CSP dạng cây"><div class="arc-settings"><label>Bài toán<select v-model="preset"><option v-for="(p,id) in cspPresets" :key="id" :value="id">{{ p.title }}</option></select></label><label>Phương pháp<select v-model="mode"><option value="ac3">AC-3 độc lập</option><option value="tree">Bộ giải CSP dạng cây</option></select></label></div><p v-if="computation.error" role="alert">{{ computation.error }}</p><template v-else><SimulationControls v-model="step" :max="computation.trace.length-1" :reset-key="key"/><CspStateView :problem="problem" :state="state"/><p class="arc-status" role="status">{{ message }}</p><div v-if="state.queue" class="arc-queue"><h4>Hàng đợi cung, đầu ở bên trái</h4><span v-for="([a,b],i) in state.queue" :key="i">{{ a }} → {{ b }}</span><span v-if="!state.queue.length">Rỗng</span></div><div v-if="state.order"><p>Thứ tự cha trước con: {{ state.order.join(' → ') }}.</p><p>Lọc ngược sửa miền của cha. Khi gán tiến, mỗi biến chỉ cần phù hợp với cha vì đồ thị là cây.</p></div><SearchTraceCode :name="mode==='tree'?'treeCspSteps':'ac3Steps'" :phase="state.phase"/></template></section></template>
<style scoped>
.csp-arc{min-width:0}.arc-settings{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.csp-arc label{display:grid;gap:6px;font:var(--fs-small)/1.7 var(--font-ui)}.csp-arc select{min-width:0;max-width:100%;min-height:44px;padding:8px;border:1px solid var(--control);border-radius:var(--radius);background:var(--paper);color:var(--ink);font:inherit}.arc-status{padding:12px;border-left:3px solid var(--tim);background:var(--tim-soft)}.arc-queue{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}.arc-queue h4{width:100%;font:600 var(--fs-small) var(--font-ui)}.arc-queue span{padding:6px;border:1px solid var(--rule);border-radius:var(--radius);font:var(--fs-small)/1.5 var(--font-ui)}select:focus-visible{outline:3px solid var(--tim);outline-offset:3px}@media(max-width:480px){.arc-settings{grid-template-columns:1fr}}
</style>
